// 図鑑の記録用キー（レシピごと）。同じ組み合わせで複数の字ができる場合、2つ目以降は「組み合わせ=字」
const RECIPE_KEYS = (() => {
  const seen = new Set();
  return RECIPES.map(([a,b,c]) => { const k = [a,b].sort().join(""); if (seen.has(k)) return k + "=" + c; seen.add(k); return k; });
})();
// WILD[字] = [{res: できる字, key: 図鑑のキー}]
const WILD = (() => {
  const w = {};
  const add = (base, res, key) => { const l = w[base] ||= []; if (!l.some(o => o.res === res)) l.push({res, key}); };
  RECIPES.forEach(([a,b,c], i) => {
    const key = RECIPE_KEYS[i];
    if (STROKES.includes(a)) add(b, c, key);
    if (STROKES.includes(b) && a !== b) add(a, c, key);
    if (a === b && STROKES.includes(a)) add(a, c, key);
  });
  for (const [base, list] of Object.entries(WILD_EXTRA)) for (const res of list) add(base, res, "W:" + base + res);
  return w;
})();
