// 字形が少し無理やりかもしれない組み合わせ（できる字: 理由）。ゲームの「見直し」画面に並ぶ。
const SUSPECT = {};
// ---- 部首タイル（スーパーレア） ----
// どの漢字にぶつけても、その字と合体できる「部首」に化ける。候補は既存のレシピから拾う（新しい字は作らない）。
// 部首として数えるのは、1画の部品とカタカナを除いた出現部品と、BUSHU_EXTRA の字。
const BUSHU_TILE = "＊";
const BUSHU_EXTRA = "耂疒示金王玉貝米目田土立石禾車羊穴广冫彳亠白寸大小戸牛犬十二工方舌比自";
const BUSHU_NOT = "ナク九乂";   // 出現部品だが部首ではないもの
const BUSHU_SET = new Set([...SPAWN.map(s => s[0]).filter(k => !STROKES.includes(k) && !BUSHU_NOT.includes(k)), ...BUSHU_EXTRA]);
// BUSHU_OPTS[字] = [{res, key, rec}]（その字と部首でできる字）
const BUSHU_OPTS = (() => {
  const o = {};
  const add = (base, i) => { const r = RECIPES[i], l = o[base] ||= []; if (!l.some(x => x.res === r[2])) l.push({res: r[2], key: RECIPE_KEYS[i], rec: r}); };
  RECIPES.forEach(([a,b], i) => {
    if (a === b) return;
    if (BUSHU_SET.has(a)) add(b, i);
    if (BUSHU_SET.has(b)) add(a, i);
  });
  return o;
})();

